import os
import azure.cognitiveservices.speech as speech_sdk

def timestamped_transcript(payload, config=None):
    config = config or {}
    speech_key = os.environ.get("AZURE_SPEECH_KEY")
    speech_region = os.environ.get("AZURE_SPEECH_REGION")

    if not speech_key or not speech_region:
        raise ValueError("AZURE_SPEECH_KEY and AZURE_SPEECH_REGION environment variables must be set.")

    speech_config = speech_sdk.SpeechConfig(subscription=speech_key, region=speech_region)
    # Request word-level timestamps and other detailed results
    speech_config.request_word_level_timestamps()
    speech_config.output_format = speech_sdk.OutputFormat.Detailed

    audio_config = speech_sdk.AudioConfig(filename=payload)
    speech_recognizer = speech_sdk.SpeechRecognizer(speech_config=speech_config, audio_config=audio_config)

    speech_result = speech_recognizer.recognize_once_async().get()

    if speech_result.reason == speech_sdk.ResultReason.RecognizedSpeech:
        import json
        detail_json = json.loads(speech_result.json)

        word_timestamps = []
        for word_data in detail_json.get("Words", []):
            word_timestamps.append({
                "word": word_data.get("Word"),
                "offset_ms": word_data.get("Offset"),
                "duration_ms": word_data.get("Duration")
            })

        result = {
            "transcript": speech_result.text,
            "word_timestamps": word_timestamps
        }
    elif speech_result.reason == speech_sdk.ResultReason.NoMatch:
        result = {"transcript": "No speech could be recognized.", "word_timestamps": []}
    elif speech_result.reason == speech_sdk.ResultReason.Canceled:
        cancellation_details = speech_result.cancellation_details
        result = {
            "error": f"Speech Recognition canceled: {cancellation_details.reason}.",
            "details": cancellation_details.error_details,
            "word_timestamps": []
        }
    else:
        result = {"error": f"An unexpected result reason occurred: {speech_result.reason}", "word_timestamps": []}
    return result
